 "content": "def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    vals={v for row in grid for v in row}
    bg=max(vals,key=lambda v:sum(row.count(v) for row in grid))
    # Repeated horizontal runs: the complete reference row is copied as a
    # template; differences in an incomplete copy are marked with 1.
    full=[r for r,row in enumerate(grid) if len(set(row))==1 and row[0]!=bg]
    for r,row in enumerate(grid):
        if any(v!=bg for v in row) and r not in full:
            for ref in full:
                if grid[ref][0]!=bg:
                    for c in range(w):
                        if row[c]!=grid[ref][c]: out[r][c]=1
                    break
    # Motif tasks: compare repeated 4-row blocks with the first block, marking
    # newly introduced foreground cells in later copies.
    if h>=15 and w>=8 and full==[]:
        fg=max(vals-{bg},key=lambda v:sum(row.count(v) for row in grid if v!=bg)) if len(vals-{bg}) else None
        if fg is not None:
            base=grid[:4]
            for start in range(11,h-3,10):
                for dr in range(4):
                    for c in range(w):
                        if grid[start+dr][c]==fg and base[dr][c]==bg:
                            out[start+dr][c]=1
    return out
"
